cd /home/user/rork-app && echo "=== Verify AI provider state after Render deploy ===" && curl -sS https://api.ivxholding.com/health 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const p=d.ivxSeniorDeveloperProviderVerification||{};
console.log('bootTime:', d.bootTime);
console.log('providerState:', p.providerState);
console.log('lastHttpStatus:', p.lastHttpStatus);
console.log('keyPrefix:', p.keyPrefix);
console.log('credentialValid:', p.credentialValid);
console.log('lastValidationTime:', p.lastValidationTime);
console.log('provider:', p.provider);
console.log('model:', p.model);
" 2>&1 && echo "" && echo "=== Trigger live AI call to force provider validation ===" && curl -sS -X POST https://api.ivxholding.com/public/chat -H "Content-Type: application/json" -d '{"message":"What is the capital of France?","roomId":"ai-test"}' -m 30 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
console.log('ok:', d.ok);
console.log('source:', d.source);
console.log('answer:', (d.answer||'').slice(0,200));
console.log('model:', d.model);
" 2>&1 && echo "" && echo "=== Re-check provider state after live call ===" && curl -sS https://api.ivxholding.com/health 2>/dev/null | bun -e "
const d=JSON.parse(require('fs').readFileSync('/dev/stdin','utf8'));
const p=d.ivxSeniorDeveloperProviderVerification||{};
console.log('providerState:', p.providerState);
console.log('lastHttpStatus:', p.lastHttpStatus);
console.log('lastValidationTime:', p.lastValidationTime);
" 2>&1

